import 'package:flutter/material.dart';
import '../app_state.dart';
import '../domain/models.dart';
import '../services/navigation_service.dart';
import '../services/location_service.dart';
import 'map_screen.dart';

class DeliveryScreen extends StatelessWidget {
  final AppState state;
  const DeliveryScreen({super.key,required this.state});
  bool _completed(DeliveryPackage p)=>p.status==DeliveryStatus.delivered;
  bool _firstPass(DeliveryPackage p)=>p.status==DeliveryStatus.pending||p.status==DeliveryStatus.current;
  DeliveryPackage? _next(){for(final p in state.packages){if(_firstPass(p))return p;}return null;}
  int _done()=>state.packages.where(_completed).length;
  DeliveryPackage? _after(DeliveryPackage current){var found=false;for(final p in state.packages){if(p.id==current.id){found=true;continue;}if(found&&_firstPass(p))return p;}return null;}

  @override Widget build(BuildContext context)=>AnimatedBuilder(animation:state,builder:(context,_){final p=_next();final total=state.packages.length;final done=_done();final pending=state.packages.where(_firstPass).length;final retry=state.packages.where((x)=>x.status==DeliveryStatus.absent||x.status==DeliveryStatus.addressProblem||x.status==DeliveryStatus.skipped).length;if(p==null)return Scaffold(appBar:AppBar(title:const Text('Passagem concluída')),body:Center(child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.task_alt,size:72),const SizedBox(height:16),Text(retry==0?'Rota finalizada':'Passagem finalizada',style:Theme.of(context).textTheme.headlineMedium,textAlign:TextAlign.center),const SizedBox(height:8),Text(retry==0?'$done entregas concluídas':'$done entregues • $retry para tentar novamente',textAlign:TextAlign.center),const SizedBox(height:20),FilledButton.icon(onPressed:()=>Navigator.pop(context),icon:const Icon(Icons.home_outlined),label:Text(retry==0?'Voltar para minha rota':'Ver pendências'))]))));final i=state.packages.indexWhere((e)=>e.id==p.id);final processed=total-pending;final progress=total==0?0.0:processed/total;final after=_after(p);return Scaffold(appBar:AppBar(title:Text('Entrega ${processed+1} de $total'),actions:[IconButton(tooltip:'Ver rota no mapa',onPressed:state.locatedCount==0?null:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>RouteMapScreen(state:state))),icon:const Icon(Icons.map_outlined))]),body:SafeArea(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[LinearProgressIndicator(value:progress),const SizedBox(height:6),Text('$pending nesta passagem • $done entregues',textAlign:TextAlign.center),const SizedBox(height:12),Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(p.label,style:Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold))),if(p.pinned)const Chip(avatar:Icon(Icons.push_pin,size:16),label:Text('Fixada'))]),const SizedBox(height:8),Container(width:double.infinity,padding:const EdgeInsets.all(12),decoration:BoxDecoration(color:Theme.of(context).colorScheme.primaryContainer,borderRadius:BorderRadius.circular(12)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('PEGUE ESTE PACOTE',style:TextStyle(fontWeight:FontWeight.bold)),Text(p.physicalZone?.trim().isNotEmpty==true?p.physicalZone!:'Sem posição de carga',style:Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold)),if(p.shortTracking!=null)Text('Código ${p.shortTracking}')]))]))),Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('ENDEREÇO',style:TextStyle(fontWeight:FontWeight.bold)),const SizedBox(height:6),Text(p.address.formatted.isEmpty?p.address.raw:p.address.formatted,style:Theme.of(context).textTheme.titleMedium)]))),if(after!=null)Padding(padding:const EdgeInsets.symmetric(horizontal:4,vertical:4),child:Text('Depois: ${after.physicalZone?.trim().isNotEmpty==true?after.physicalZone:after.label}',maxLines:1,overflow:TextOverflow.ellipsis)),const Spacer(),FilledButton.tonalIcon(onPressed:()=>NavigationService().openWaze(p),icon:const Icon(Icons.navigation),label:const Padding(padding:EdgeInsets.all(13),child:Text('IR PELO WAZE'))),const SizedBox(height:8),Row(children:[Expanded(child:OutlinedButton.icon(onPressed:()=>_finish(context,i,p,DeliveryStatus.skipped,'Pulou'),icon:const Icon(Icons.skip_next),label:const Text('Pular'))),const SizedBox(width:8),Expanded(child:OutlinedButton.icon(onPressed:()=>_finish(context,i,p,DeliveryStatus.absent,'Ausente'),icon:const Icon(Icons.person_off_outlined),label:const Text('Ausente')))]),const SizedBox(height:8),FilledButton.icon(onPressed:()=>_finish(context,i,p,DeliveryStatus.delivered,'Entregue'),icon:const Icon(Icons.check_circle),label:const Padding(padding:EdgeInsets.all(13),child:Text('ENTREGUE • PRÓXIMO'))),const SizedBox(height:4),Row(children:[Expanded(child:TextButton.icon(onPressed:()=>_addressProblem(context,i,p),icon:const Icon(Icons.wrong_location_outlined),label:const Text('Endereço errado'))),Expanded(child:TextButton.icon(onPressed:()=>_reoptimize(context),icon:const Icon(Icons.auto_fix_high),label:const Text('Reotimizar')))])]))));});

  Future<void> _finish(BuildContext context,int i,DeliveryPackage p,DeliveryStatus status,String label)async{final delivered=status==DeliveryStatus.delivered;String? receivedBy;if(delivered){receivedBy=await _askReceiver(context);if(receivedBy==null)return;}await state.update(i,p.copyWith(status:status,receivedBy:receivedBy,completedAt:delivered?DateTime.now():null,clearCompletedAt:!delivered));if(!context.mounted)return;final next=_next();if(delivered){await _showDeliveryConfirmation(context,hasNext:next!=null);if(next!=null&&context.mounted){await Navigator.of(context).pushReplacement(MaterialPageRoute(builder:(_)=>DeliveryScreen(state:state)));}return;}ScaffoldMessenger.of(context).clearSnackBars();ScaffoldMessenger.of(context).showSnackBar(SnackBar(duration:const Duration(seconds:2),content:Text(next==null?'$label. Passagem concluída.':'$label. Próximo: ${next.physicalZone?.trim().isNotEmpty==true?next.physicalZone:next.label}')));}

  Future<String?> _askReceiver(BuildContext context)async{final controller=TextEditingController();String? error;final result=await showDialog<String>(context:context,barrierDismissible:false,builder:(d)=>StatefulBuilder(builder:(context,setDialogState)=>AlertDialog(title:const Text('Quem recebeu?'),content:TextField(controller:controller,autofocus:true,textCapitalization:TextCapitalization.words,textInputAction:TextInputAction.done,decoration:InputDecoration(labelText:'Nome de quem recebeu',hintText:'Ex.: Maria',errorText:error),onSubmitted:(_){final name=controller.text.trim();if(name.isEmpty){setDialogState(()=>error='Informe o nome para concluir a entrega.');}else{Navigator.pop(d,name);}}),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('Cancelar')),FilledButton(onPressed:(){final name=controller.text.trim();if(name.isEmpty){setDialogState(()=>error='Informe o nome para concluir a entrega.');return;}Navigator.pop(d,name);},child:const Text('Confirmar entrega'))])));controller.dispose();return result;}

  Future<void> _showDeliveryConfirmation(BuildContext context,{required bool hasNext})async{await showGeneralDialog<void>(context:context,barrierDismissible:false,barrierLabel:'Entrega confirmada',barrierColor:Colors.black45,transitionDuration:const Duration(milliseconds:180),pageBuilder:(dialogContext,_,__)=>Center(child:Material(color:Colors.transparent,child:Container(margin:const EdgeInsets.symmetric(horizontal:32),padding:const EdgeInsets.symmetric(horizontal:28,vertical:30),decoration:BoxDecoration(color:Theme.of(dialogContext).colorScheme.surface,borderRadius:BorderRadius.circular(24)),child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(Icons.check_circle,size:76,color:Theme.of(dialogContext).colorScheme.primary),const SizedBox(height:14),Text('Pacote entregue!',style:Theme.of(dialogContext).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold),textAlign:TextAlign.center),const SizedBox(height:8),Text(hasNext?'Indo para a próxima entrega…':'Rota concluída!',style:Theme.of(dialogContext).textTheme.titleMedium,textAlign:TextAlign.center)])))),transitionBuilder:(context,animation,_,child)=>FadeTransition(opacity:animation,child:ScaleTransition(scale:Tween<double>(begin:.94,end:1).animate(animation),child:child)));await Future<void>.delayed(const Duration(milliseconds:900));if(context.mounted&&Navigator.of(context,rootNavigator:true).canPop())Navigator.of(context,rootNavigator:true).pop();}

  Future<void> _addressProblem(BuildContext context,int i,DeliveryPackage p)async{final ok=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:const Text('Problema com o endereço?'),content:const Text('O pacote ficará em Problemas para conferência. Ele não será tratado como entregue.'),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Marcar e seguir'))]));if(!context.mounted)return;if(ok==true)await _finish(context,i,p,DeliveryStatus.addressProblem,'Separado para conferência');}
  Future<void> _reoptimize(BuildContext context)async{try{final pos=await LocationService().current();await state.optimizeFrom(pos.latitude,pos.longitude);if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Entregas restantes reotimizadas. As posições físicas da carga foram mantidas.')));}catch(e){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}}
}
